CREATE TABLE "TB_DATASET_VER" (
  "DATASET_VER" VARCHAR(50) PRIMARY KEY,
  "DATASET_STS" VARCHAR(20) NOT NULL,
  "FROZEN_DTTM" TIMESTAMPTZ,
  "DESCRIPTION" VARCHAR(2000) NOT NULL,
  "CONTRACT_JSON" JSONB NOT NULL DEFAULT '{}'::jsonb,
  "CRT_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "CK_TB_DATASET_VER_01" CHECK ("DATASET_STS" IN ('DRAFT','FROZEN','RETIRED'))
);

CREATE TABLE "TB_DATASET_ITEM" (
  "DATASET_ITEM_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "DATASET_VER" VARCHAR(50) NOT NULL REFERENCES "TB_DATASET_VER"("DATASET_VER"),
  "ITEM_CD" VARCHAR(80) NOT NULL,
  "ITEM_CLASS" VARCHAR(20) NOT NULL,
  "PROVIDER_CD" VARCHAR(50),
  "STORAGE_NAME" VARCHAR(100),
  "AVAILABLE_YN" CHAR(1) NOT NULL,
  "USED_BY_ALGORITHM_YN" CHAR(1) NOT NULL,
  "MIN_BASE_DT" DATE,
  "MAX_BASE_DT" DATE,
  "ROW_CNT" BIGINT,
  "REASON_TXT" VARCHAR(2000),
  "CRT_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "UK_TB_DATASET_ITEM_01" UNIQUE ("DATASET_VER","ITEM_CD"),
  CONSTRAINT "CK_TB_DATASET_ITEM_01" CHECK ("ITEM_CLASS" IN ('CORE','SUPPLEMENT','FUTURE')),
  CONSTRAINT "CK_TB_DATASET_ITEM_02" CHECK ("AVAILABLE_YN" IN ('Y','N') AND "USED_BY_ALGORITHM_YN" IN ('Y','N'))
);
CREATE INDEX "IDX_TB_DATASET_ITEM_01" ON "TB_DATASET_ITEM"("DATASET_VER","ITEM_CLASS","ITEM_CD");

