ALTER TABLE "TB_HIST_RECALC_RUN"
  ADD COLUMN "ALGORITHM_VER" VARCHAR(50),
  ADD COLUMN "DATASET_VER" VARCHAR(50) REFERENCES "TB_DATASET_VER"("DATASET_VER"),
  ADD COLUMN "INPUT_COVERAGE_RT" NUMERIC(7,4),
  ADD COLUMN "RECONSTRUCTION_QUALITY" VARCHAR(20),
  ADD COLUMN "LOOKAHEAD_CHECK_YN" CHAR(1);

UPDATE "TB_HIST_RECALC_RUN" r SET
  "ALGORITHM_VER"='MARKET_ALGORITHM_V2',
  "DATASET_VER"='DATASET_V1',
  "INPUT_COVERAGE_RT"=COALESCE((SELECT round(100.0*count(*) FILTER (WHERE i."AVAILABLE_YN"='Y')/NULLIF(count(*),0),4) FROM "TB_HIST_RECALC_INPUT" i WHERE i."HIST_RECALC_RUN_ID"=r."HIST_RECALC_RUN_ID"),0),
  "RECONSTRUCTION_QUALITY"=CASE WHEN r."DATA_STS"='COMPLETE' THEN 'FULL' ELSE 'PARTIAL' END,
  "LOOKAHEAD_CHECK_YN"='N';

ALTER TABLE "TB_HIST_RECALC_RUN"
  ALTER COLUMN "ALGORITHM_VER" SET NOT NULL,
  ALTER COLUMN "DATASET_VER" SET NOT NULL,
  ALTER COLUMN "INPUT_COVERAGE_RT" SET NOT NULL,
  ALTER COLUMN "RECONSTRUCTION_QUALITY" SET NOT NULL,
  ALTER COLUMN "LOOKAHEAD_CHECK_YN" SET NOT NULL,
  ADD CONSTRAINT "CK_TB_HIST_RECALC_RUN_06" CHECK ("INPUT_COVERAGE_RT" BETWEEN 0 AND 100),
  ADD CONSTRAINT "CK_TB_HIST_RECALC_RUN_07" CHECK ("RECONSTRUCTION_QUALITY" IN ('FULL','PARTIAL','ESTIMATED')),
  ADD CONSTRAINT "CK_TB_HIST_RECALC_RUN_08" CHECK ("LOOKAHEAD_CHECK_YN" IN ('Y','N'));

COMMENT ON TABLE "TB_DATASET_VER" IS '계산·판단·브리핑·RECALC·OUTCOME 검증에 사용하는 동결 데이터 계약';
COMMENT ON TABLE "TB_DATASET_ITEM" IS '동결 데이터 계약의 CORE, SUPPLEMENT, FUTURE 항목';
COMMENT ON COLUMN "TB_HIST_RECALC_RUN"."LOOKAHEAD_CHECK_YN" IS '모든 입력이 Case AS_OF_DTTM 이전 공개 데이터인지 검증 완료 여부';
